"use client";
/* Pidge, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Pidge(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("pidge"); }, []);
  return React.createElement("piix-pal", { "pal": "pidge", ...piixAttrs(props) });
}

export default Pidge;
